use crate::{catalog,model::*,rules::*,unit_support::*};
fn settle(g:&mut Game){for _ in 0..160{if g.pending.is_some(){resolve_choice(g);}else if !g.stack.is_empty(){pass(g);}else{return}}panic!("LC04 did not finish")}
fn start(g:&mut Game)->String{fund(g,0,"JC042",7);let id=held(g,"LC04",0);act(g,0,Action{card_id:Some(id.clone()),..Action::new("deploy")});id}
#[test]fn lc04_identity_original_red_society_and_blood_loyalty(){assert_current_serial_catalog();let c=catalog::card("LC04");assert_eq!(c.color,"红");assert_eq!(c.society,"王座会");assert_eq!(c.loyalty,["鲜血";3]);assert_eq!(c.cost,7);assert_eq!(c.defense,Some(3));assert!(!c.supported);assert!(definition("LC04").traits.chaos);assert!(CardFilter::PrintedSociety("王座会".into()).matches(c));assert!(!CardFilter::PrintedColor("蓝".into()).matches(c));let mut g=game();fund(&mut g,0,"CQ12",7);assert!(!g.loyalty(0,"LC04"));fund(&mut g,0,"JC042",3);assert!(g.loyalty(0,"LC04"));}
#[test]fn lc04_real_entry_discards_then_sacrifices_with_restore(){let mut g=game();for s in 0..4{held(&mut g,"JC125",s);field(&mut g,"JC125",s);let id=field(&mut g,"JC125",s);g.board_mut(&id).unwrap().face_down=true;fund(&mut g,s,"JC125",1);}start(&mut g);let mut discards=0;let mut sacrifices=0;for _ in 0..160{if let Some(p)=g.pending.clone(){if p.choice.kind=="discard"{assert_eq!(sacrifices,0);discards+=1;}if p.choice.kind=="lc04-sacrifice"{assert_eq!(discards,4);sacrifices+=1;}resolve_choice(&mut g);}else if !g.stack.is_empty(){pass(&mut g);}else{break}}assert_eq!(discards,4);assert_eq!(sacrifices,12);assert_eq!(g.players[0].assets.len(),7);for s in 1..4{assert!(g.players[s].assets.is_empty());}assert!(g.in_play_cards().iter().any(|(_,c)|c.definition=="LC04"));restore(&mut g);}
#[test]fn lc04_empty_categories_skip_but_self_sacrifice_is_mandatory(){let mut g=game();let id=start(&mut g);settle(&mut g);assert!(g.in_play(&id).is_none());assert!(g.players[0].graveyard.iter().any(|c|c.definition=="LC04"));assert_eq!(g.players[0].assets.len(),6);}
#[test]fn lc04_pending_corruption_and_duplicate_selection_rejected(){let mut g=game();field(&mut g,"JC125",0);start(&mut g);for _ in 0..80{if g.pending.as_ref().is_some_and(|p|p.choice.kind=="lc04-sacrifice"){break}if g.pending.is_some(){resolve_choice(&mut g)}else{pass(&mut g)}}let p=g.pending.clone().unwrap();let id=p.choice.options[0].id.clone();reject(&mut g,p.seat,Action{choice_id:Some(p.choice.id.clone()),selected:Some(vec![id.clone(),id]),..Action::new("choose")});for n in 0..5{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.choice.min=Some(0),1=>p.seat=1,2=>if let ChoiceResolution::Frame{frame,..}=&mut p.resolution{frame.source.card.definition="JC125".into()},3=>if let ChoiceResolution::Frame{choice:FrameChoice::LC04(v),..}=&mut p.resolution{v.chosen.push(None)},_=>if let ChoiceResolution::Frame{frame,..}=&p.resolution{x.effects.push_back(Effect::Frame{frame:frame.clone()})}}assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err(),"mutation{n}");let mut r=crate::jc029_tests::envelope(&g);r.game=x;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}settle(&mut g);}
#[test]fn lc04_selected_attachment_and_host_each_depart_once_generated_vanishes(){let mut g=game();let host=field(&mut g,"JC125",0);let a=g.make_card("JC073",0);let attachment=a.id.clone();g.attachments.push(Attachment{card:a,host_id:host.clone()});let mut token=g.make_generated(crate::generated::GeneratedKind::Cultist,0).unwrap();token.face_down=true;let hidden=token.id.clone();g.regions[0].cards.push(token);start(&mut g);settle(&mut g);for id in [host,attachment,hidden]{assert!(g.in_play(&id).is_none());}assert_eq!(g.players[0].graveyard.iter().filter(|c|c.definition=="JC073").count(),1);assert!(!g.batch3_physical_cards().any(|c|c.generated.is_some()));}
#[test]fn lc04_source_departure_in_response_keeps_trigger_and_current_choices(){let mut g=game();let victim=field(&mut g,"JC125",1);let id=start(&mut g);for _ in 0..40{if g.stack.last().and_then(|i|i.frame.as_ref()).is_some_and(|f|f.ability_key==crate::lc04::KEY){break}pass(&mut g)}let current=g.stack.last().unwrap().frame.as_ref().unwrap().source.card.id.clone();assert_ne!(id,current);g.return_hand(&current);restore(&mut g);settle(&mut g);assert!(g.in_play(&victim).is_none());}
#[test]fn lc04_pending_choices_private_and_control_change_rejected(){let mut g=game();let victim=field(&mut g,"JC125",0);start(&mut g);for _ in 0..80{if g.pending.as_ref().is_some_and(|p|p.choice.kind=="lc04-sacrifice"){break}if g.pending.is_some(){resolve_choice(&mut g)}else{pass(&mut g)}}let p=g.pending.clone().unwrap();for s in 1..4{assert!(g.view(s).pending_choice.is_none());}choose(&mut g,vec![victim.clone()]);let mut x=g.clone();x.board_mut(&victim).unwrap().controller=1;assert!(Game::from_persisted(&serde_json::to_string(&x).unwrap()).is_err());assert_eq!(p.seat,0);settle(&mut g);}
fn trace_finish(t:&mut crate::abi112_review_play_tests::Trace){for _ in 0..200{if let Some(p)=t.room.game.pending.clone(){let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();t.choose(ids);}else if !t.room.game.stack.is_empty(){t.pass();}else{return}}panic!("trace bounded")}
fn stamp(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn explicit()->serde_json::Value{let mut g=game();for s in 0..4{held(&mut g,"JC125",s);let host=field(&mut g,"JC125",s);let a=g.make_card("JC073",s);g.attachments.push(Attachment{card:a,host_id:host});let mut c=g.make_generated(crate::generated::GeneratedKind::Cultist,s).unwrap();c.face_down=true;g.regions[0].cards.push(c);fund(&mut g,s,"JC125",1);}fund(&mut g,0,"JC042",7);let id=held(&mut g,"LC04",0);let mut t=crate::abi112_review_play_tests::Trace::new(g,"lc04-four-categories-explicit".into(),903);t.action(0,Action{card_id:Some(id),..Action::new("deploy")});trace_finish(&mut t);assert!(t.room.game.attachments.is_empty());assert!(!t.room.game.batch3_physical_cards().any(|c|c.generated.is_some()));let mut v=t.value();v["construction"]=serde_json::json!({"explicitLayout":true,"firstMechanismStep":0});stamp(v)}
fn natural()->serde_json::Value{use crate::{deck,abi112_review_play_tests::Trace};fn construct(seed:u64)->Game{let mut d=deck::preset("watchers").unwrap();d.id="lc04-private".into();d.society_id=None;d.core_card_id=None;d.cards=[("LC04",1),("JC042",3),("JC125",46)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id=="LC04").unwrap().supported=true;let d=deck::validate_with_cards(d,&cards).unwrap();let mut other=deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=deck::validate(other).unwrap();let mut g=Game::new("lc04".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
let(seed,g)=(1..30000).find_map(|seed|{let g=construct(seed);let h=&g.players[0].hand;(h.iter().any(|c|c.definition=="LC04")&&h.iter().filter(|c|c.definition=="JC042").count()==3).then_some((seed,g))}).expect("legal seeded initial hand");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"lc04-natural-fifty".into(),904);let mut deployed=false;for _ in 0..2200{if let Some(p)=t.room.game.pending.clone(){if matches!(&p.resolution,ChoiceResolution::Forecast{..}|ChoiceResolution::Frame{choice:FrameChoice::Forecast{..},..}){t.action(p.seat,Action{choice_id:Some(p.choice.id),top:Some(p.choice.options.iter().map(|o|o.id.clone()).collect()),bottom:Some(vec![]),..Action::new("choose")});continue}let mut options=p.choice.options.iter().collect::<Vec<_>>();options.sort_by_key(|o|t.room.game.players[p.seat].hand.iter().any(|c|c.id==o.id&&["LC04","JC042"].contains(&c.definition.as_str())));t.choose(options.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect());continue}if deployed&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break}if !t.room.game.stack.is_empty(){t.pass();continue}let g=&t.room.game;let legal=g.legal_actions(0);let name=|a:&Action,id:&str|a.card_id.as_ref().is_some_and(|key|g.players[0].hand.iter().any(|c|&c.id==key&&c.definition==id));let a=legal.iter().find(|a|a.action.kind=="deploy"&&name(&a.action,"LC04")).or_else(||legal.iter().filter(|a|a.action.kind=="asset"&&!name(&a.action,"LC04")).min_by_key(|a|!name(&a.action,"JC042")));if let Some(a)=a{let a=a.action.clone();deployed|=a.kind=="deploy";t.action(0,a)}else{t.pass()}}
assert!(deployed&&t.room.game.stack.is_empty()&&t.room.game.pending.is_none());assert!(t.room.game.players[0].graveyard.iter().any(|c|c.definition=="LC04"));let mut v=t.value();let first=v["steps"].as_array().unwrap().iter().position(|s|s["command"]["action"]["action"]["kind"]=="deploy").unwrap();v["construction"]=serde_json::json!({"seed":seed,"deck":deck,"ordinaryCards":50,"privateRegistryOnly":true,"noLayoutOrResourceMutation":true,"firstMechanismStep":first});stamp(v)}
#[test]fn lc04_native_export(){let cases=vec![natural(),explicit()];let mut bindings=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/lc04.rs",include_bytes!("lc04.rs").as_slice()),("rust-game/src/lc04_tests.rs",include_bytes!("lc04_tests.rs").as_slice())]{bindings["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}let v=serde_json::json!({"cases":cases,"catalog":catalog::catalog(),"sourceBindings":bindings});if let Ok(path)=std::env::var("LC04_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec(&v).unwrap()).unwrap();}}
#[test]fn lc04_real_payment_rejects_red_without_blood_and_chaos_destination(){let mut g=game();fund(&mut g,0,"CQ12",7);let id=held(&mut g,"LC04",0);reject(&mut g,0,Action{card_id:Some(id.clone()),..Action::new("deploy")});g.players[0].assets.clear();fund(&mut g,0,"JC042",7);reject(&mut g,0,Action{card_id:Some(id.clone()),region:Some(0),..Action::new("deploy")});reject(&mut g,0,Action{card_id:Some(id.clone()),selected:Some(vec![]),..Action::new("deploy")});act(&mut g,0,Action{card_id:Some(id),..Action::new("deploy")});settle(&mut g);}
#[test]fn lc04_conceal_defers_entry_until_actual_paid_reveal(){let mut g=game();fund(&mut g,0,"JC042",8);let id=held(&mut g,"LC04",0);act(&mut g,0,Action{card_id:Some(id),region:Some(0),..Action::new("conceal")});settle(&mut g);let id=g.regions[0].cards.iter().find(|c|c.definition=="LC04").unwrap().id.clone();assert!(g.board(&id).unwrap().1.face_down);assert!(g.players[0].graveyard.is_empty());g.begin_window(Window::Action(0));act(&mut g,0,Action{card_id:Some(id),..Action::new("reveal")});settle(&mut g);assert!(g.players[0].graveyard.iter().any(|c|c.definition=="LC04"));}
#[test]fn lc04_leader_conflict_and_blood_departure_use_existing_queues(){let mut g=game();let old=field(&mut g,"JC052",0);let host=field(&mut g,"JC029",0);let blood=g.make_card("XQ14",0);g.attachments.push(Attachment{card:blood,host_id:host.clone()});let gear=g.make_card("JC073",0);let gear_id=gear.id.clone();g.attachments.push(Attachment{card:gear,host_id:host.clone()});g.players[0].society_zone.card=Some(g.make_card("MSBQ01",0));start(&mut g);let(mut leader,mut blood)=(false,false);for _ in 0..180{if let Some(p)=g.pending.clone(){let ids=if p.choice.title.starts_with("领袖："){leader=true;vec![old.clone()]}else if p.choice.kind=="lc04-sacrifice"&&p.choice.title.ends_with("角色"){vec![host.clone()]}else if p.choice.kind=="lc04-sacrifice"&&p.choice.title.ends_with("附属"){vec![gear_id.clone()]}else if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==crate::msbq01::KEY){blood=true;vec!["accept".into()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};choose(&mut g,ids);}else if !g.stack.is_empty(){pass(&mut g)}else{break}}assert!(leader&&blood,"leader={leader}, blood={blood}");assert!(g.sealed_cards.iter().any(|s|s.card.definition=="XQ14"));assert!(g.in_play(&old).is_none()&&g.in_play(&host).is_none());restore(&mut g);}
